import yaml, subprocess
targets = {
 '.github/workflows/ci.yml': ['Upload archive to GitHub Release', 'Upload bundle to GitHub Release'],
 '.github/workflows/build-macos.yml': ['Archive and upload CLI bundle', 'Upload extension to the release'],
}
for wf, names in targets.items():
    d = yaml.safe_load(open(wf))
    for jid, job in d['jobs'].items():
        for st in job.get('steps', []):
            if st.get('name') in names:
                p = subprocess.run(['bash', '-n'], input=st['run'], text=True, capture_output=True)
                print(f"{wf} :: {jid} :: {st['name']} -> {'OK' if p.returncode==0 else p.stderr[:200]}")
